def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        if history[0][1] == 'C' and history[1][1] == 'C':
            return 'D'
        else:
            if history[-1][1] == 'D':
                return 'D'
            return 'C'

    last_me, last_opp = history[-1]
    opp_defections = sum(1 for _, o in history if o == 'D')

    if opp_defections > n * 0.6:
        return 'D'

    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    probed = (n >= 3 and history[2][0] == 'D' and history[2][1] == 'C')
    retaliated_to_probe = False
    if n >= 4 and probed:
        if history[3][1] == 'D':
            retaliated_to_probe = True

    in_exploit_mode = probed and not retaliated_to_probe and opp_defections == 0

    if last_opp == 'D':
        if opp_defections > n * 0.4:
            return 'D'
        if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        return 'C'

    if in_exploit_mode:
        if n >= 2:
            prev_me, prev_opp = history[-2]
            if prev_me == 'C' and prev_opp == 'C' and last_me == 'C' and last_opp == 'C':
                return 'D'
        return 'C'
    else:
        return 'C'
